local DATA_DIR = "sanc_data"
local hasFS = type(isfile)=="function"
    and type(readfile)=="function"
    and type(writefile)=="function"

local HttpService = game:GetService("HttpService")

if hasFS and type(makefolder)=="function" then
    local okFolder = (type(isfolder)=="function" and isfolder(DATA_DIR)) or false
    if not okFolder then
        pcall(makefolder, DATA_DIR)
    end
end

getgenv().key = getgenv().key or getfenv().key
local loaderName = DATA_DIR .. "/sanctuary_loader_" .. hjgrtdbg7uiytasgd7vsbhadvgad.z87889cf .. ".lua"
local loaderMetaName = DATA_DIR .. "/sanctuary_loader_" .. hjgrtdbg7uiytasgd7vsbhadvgad.z87889cf .. ".json"
local loaderURL  = "https://cdn.snc.dev/loader/v1"

local function findRequest()
    if request then return request end
    if http_request then return http_request end
    if http and http.request then return http.request end
end

local function http_get(url)
    local req = findRequest()
    if req then
        local ok, res = pcall(req, { Url = url, Method = "GET" })
        if ok and res and type(res.Body)=="string" then
            return res.Body
        end
    end
    return game:HttpGet(url)
end

local function ensure_loader()
    local forceDownload = false
    local cachedUploadDate = nil
    local expectedUploadDate = tonumber(hjgrtdbg7uiytasgd7vsbhadvgad.t774e6f7)

    if hasFS and isfile(loaderMetaName) then
        local okMeta, metaStr = pcall(readfile, loaderMetaName)
        if okMeta and type(metaStr) == "string" and #metaStr > 0 then
            local okDecode, metaTable = pcall(function()
                return HttpService:JSONDecode(metaStr)
            end)
            if okDecode and type(metaTable) == "table" then
                cachedUploadDate = tonumber(metaTable.loaderUploadDate)
            end
        end
    end

    if not cachedUploadDate then
        forceDownload = true
    elseif expectedUploadDate and expectedUploadDate > cachedUploadDate then
        forceDownload = true
    end

    if hasFS and isfile(loaderName) and not forceDownload then
        local ok, src = pcall(readfile, loaderName)
        if ok and type(src)=="string" and #src > 50 then
            return src
        end
    end

    local src = http_get(loaderURL)

    if hasFS then
        pcall(writefile, loaderName, src)
        local uploadValue = expectedUploadDate or cachedUploadDate or os.time()
        local okEncode, metaStr = pcall(function()
            return HttpService:JSONEncode({
                t774e6f7= uploadValue
            })
        end)
        if okEncode and metaStr then
            pcall(writefile, loaderMetaName, metaStr)
        end
    end

    return src
end

local function run_loader()
    local raw = ensure_loader()
    local chunk, err = loadstring(raw, "SanctuaryLoader")
    if not chunk then
        error("Sanctuary Loader error: " .. tostring(err))
    end
    return chunk()
end

return run_loader()